import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {LAB_EVENTS,DEFAULT_EXPERIMENTS,readExperiment,experimentURL,validateExperimentState} from '../web/experiment-state.mjs';

// Literal examples are independently declared, rather than generated by the serializer under test.
const wind='experiment=wind-1&event=joplin-2011&peak=100&radius=500&background=20&probe-x=1.3&probe-y=-0.4&area=1&coefficient=1.2&travel=30&offset=-0.7&threshold=50&capacity=1.6&sample=300';
const form='experiment=form-1&event=blackwell-1955&shape=rope&condensation=65&azimuth=-35&elevation=24&distance=8.2&dust=0&quality=3600&sequence=1&coverage=bounded&rate=15&position=0.5&phase=15';
const procedural='experiment=form-2&shape=cone&condensation=100&azimuth=25&elevation=12&distance=7&dust=1&quality=3600&sequence=0&coverage=continuous&rate=1&position=0&phase=123.5&model=kinematic-v1';

test('literal procedural form links retain their model version while old links keep the legacy domain',()=>{
  const next=readExperiment(procedural,'form');assert.equal(next.status,'restored');assert.equal(next.state.model,'kinematic-v1');assert.equal(next.state.phase,123.5);
  const url=experimentURL('https://example.test/study.html','form',null,next.state);assert.equal(url.searchParams.get('experiment'),'form-2');assert.deepEqual(readExperiment(url.search,'form').state,next.state);
  const legacy=readExperiment(form.replace('sequence=1','sequence=0').replace('phase=15','phase=1000000000'),'form');assert.equal(legacy.status,'restored');assert.equal(legacy.state.phase,1e9);assert.equal(Object.hasOwn(legacy.state,'model'),false);
  assert.equal(experimentURL('https://example.test/study.html','form',null,legacy.state).searchParams.get('experiment'),'form-1');
});

test('procedural version refuses missing/unknown models, overflow phase and unversioned model injection',()=>{
  for(const search of [procedural.replace('&model=kinematic-v1',''),procedural.replace('kinematic-v1','future-model'),procedural.replace('phase=123.5','phase=86400.1'),procedural+'&model=kinematic-v1',form+'&model=kinematic-v1']){
    const result=readExperiment(search,'form');assert.equal(result.status,'invalid');assert.equal(result.state,null);assert.equal(result.event,null);
  }
});
test('empty laboratories have no assigned historical storm',()=>{
  for(const kind of ['wind','form'])assert.deepEqual(readExperiment('',kind),{status:'empty',event:null,state:null,message:''});
});
test('all six documentary-only routes are valid without an experiment',()=>{
  for(const id of ['el-reno-2013','joplin-2011','blackwell-1955','tuscaloosa-birmingham-2011','moore-2013','udall-1955']){
    for(const kind of ['wind','form'])assert.deepEqual(readExperiment('?event='+id,kind),{status:'reference',event:id,state:null,message:''});
  }
});
test('literal Wind link retains the assumed inputs and one discrete sample',()=>{
  const result=readExperiment('?'+wind,'wind');assert.equal(result.status,'restored');assert.equal(result.event,'joplin-2011');
  assert.deepEqual(result.state,{peak:100,radius:500,background:20,'probe-x':1.3,'probe-y':-.4,area:1,coefficient:1.2,travel:30,offset:-.7,threshold:50,capacity:1.6,sample:300});
});
test('literal Form link retains its authored gap selection and every control',()=>{
  const result=readExperiment('?'+form,'form');assert.equal(result.status,'restored');
  assert.deepEqual(result.state,{shape:'rope',condensation:65,azimuth:-35,elevation:24,distance:8.2,dust:false,quality:3600,sequence:true,coverage:'bounded',rate:15,position:.5,phase:15});
});
test('reference changes never supply or mutate model values',()=>{
  const state=readExperiment(wind,'wind').state,before=JSON.stringify(state);
  for(const event of LAB_EVENTS){const url=experimentURL('https://example.test/wind.html#passage','wind',event.id,state);assert.deepEqual(readExperiment(url.search,'wind').state,state);assert.equal(url.hash,'#passage');}
  assert.equal(JSON.stringify(state),before);
});
test('all complete default states round trip without a selected event',()=>{
  for(const kind of ['wind','form']){
    validateExperimentState(kind,DEFAULT_EXPERIMENTS[kind]);
    const url=experimentURL('https://example.test/'+(kind==='wind'?'wind':'study')+'.html?old=value',kind,null,DEFAULT_EXPERIMENTS[kind]);
    assert.equal(url.searchParams.has('old'),false);assert.equal(url.searchParams.has('event'),false);
    assert.deepEqual(readExperiment(url.search,kind).state,DEFAULT_EXPERIMENTS[kind]);
  }
});
const invalid=[
  ['unknown event',wind.replace('joplin-2011','unknown')],
  ['duplicate event',wind+'&event=el-reno-2013'],
  ['duplicate model input',wind+'&peak=100'],
  ['unknown field',wind+'&wind_accuracy=exact'],
  ['arbitrary return URL',wind+'&return=https://example.test/'],
  ['autoplay flag',wind+'&playing=1'],
  ['unsupported version',wind.replace('wind-1','wind-2')],
  ['missing version',wind.replace('experiment=wind-1&','')],
  ['partial experiment',wind.replace('&capacity=1.6','')],
  ['nonfinite input',wind.replace('peak=100','peak=Infinity')],
  ['empty number',wind.replace('peak=100','peak=')],
  ['off-step input',wind.replace('peak=100','peak=101')],
  ['off-step decimal',wind.replace('capacity=1.6','capacity=1.61')],
  ['out of range',wind.replace('sample=300','sample=481')],
  ['fractional sample',wind.replace('sample=300','sample=300.5')],
  ['wrong lab version',wind.replace('wind-1','form-1')],
];
for(const [name,search] of invalid)test('refuse '+name+' without a partially applied event or state',()=>{
  const result=readExperiment(search,'wind');assert.equal(result.status,'invalid');assert.equal(result.event,null);assert.equal(result.state,null);
});
test('Form refuses inconsistent phase, unknown presets and nonliteral switches',()=>{
  for(const search of [form.replace('phase=15','phase=16'),form.replace('shape=rope','shape=historical'),form.replace('dust=0','dust=false'),form.replace('position=0.5','position=0.5001')])assert.equal(readExperiment(search,'form').status,'invalid');
});
test('oversized input is refused before parsing',()=>assert.equal(readExperiment('?'+('x'.repeat(2049)),'wind').status,'invalid'));
test('serialized manual Form phase is finite bounded state, without autoplay',()=>{
  const state={...DEFAULT_EXPERIMENTS.form,phase:.0000001};
  const url=experimentURL('https://example.test/study.html','form',null,state);
  assert.deepEqual(readExperiment(url.search,'form').state,state);assert.equal(url.searchParams.has('playing'),false);
  assert.throws(()=>validateExperimentState('form',{...state,phase:Infinity}));
});
test('documentary links identify existing native anchors and do not host new source media',async()=>{
  for(const event of LAB_EVENTS)for(const kind of ['form','wind']){
    const [file,anchor]=event[kind].split('#'),html=await readFile(new URL('../web/'+file,import.meta.url),'utf8');
    assert.ok(html.includes('id="'+anchor+'"'),event.id+' '+kind+' reference anchor');
    assert.ok(!/\.(?:jpg|png|mp4|webm)/.test(event[kind]));
  }
});
